function b({registerIndicator:N,sourceValues:g,nulls:f}){const d=(i,l)=>{const c=i.length,s=new Array(c).fill(NaN),a=new Array(l).fill(NaN);let t=0,o=0,r=0,n=0,e=0;for(let u=0;u<c;u++){const p=a[t],m=Number.isFinite(i[u])?i[u]:0;if(Number.isFinite(p)){const y=o;o=o-p+m,r=r-y+l*m}else n+=1,o+=m,r+=n*m,e=n*(n+1)*.5;a[t]=m,t=(t+1)%l,s[u]=e>0?r/e:NaN}return s};N({id:"oa-pma",name:"Ehlers Predictive Moving Average (PMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:7,min:1,max:5e3,step:1,tooltip:"Lookback period for WMA smoothing (Ehlers default: 7)"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"pma",type:"line",title:"PMA",style:{color:"#ffeb3b",lineWidth:2}},{key:"trigger",type:"line",title:"Trigger",style:{color:"#ff9800",lineWidth:1}}],calc(i,l){const c=Math.max(1,Math.floor(Number(l.period)||7)),s=g(i,l.source??"close"),a=i.length,t=d(s,c),o=d(t,c),r=new Array(a).fill(NaN),n=new Array(a).fill(NaN);for(let e=0;e<a;e++)Number.isFinite(s[e])&&(!Number.isFinite(t[e])||!Number.isFinite(o[e])||(r[e]=2*t[e]-o[e],n[e]=(4*t[e]-o[e])/3));return{pma:f(r),trigger:f(n)}}})}export{b as default};
